// R7 implementation guide: section 4.2.
// Public description of an image generated by rendering, not by CPU pixel upload.
// The Renderer owns color, descriptors and matching Depth behind one stable logical handle.
// Info is a value snapshot; it is not a native descriptor or a lifetime-bearing reference.

#pragma once

#include "ResourceHandle.h"
#include "TextureDesc.h"

#include <cstdint>

namespace rendering
{

// GPU-generated color output. CPU pixels and upload requests belong to TextureDesc.
// Allocate GPU-generated output storage. No CPU pixel span or upload mip array belongs here.
// R7 deliberately supports RGBA8_UNorm, one mip and one sample only.
struct RenderTargetTextureDesc
{
	std::uint32_t width = 0;
	std::uint32_t height = 0;
	TextureFormat format = TextureFormat::RGBA8_UNorm;
};

// A value snapshot. It neither owns a GPU image nor pins a particular revision.
// Read a value snapshot of the current revision.
// contentsValid is false after creation or successful size replacement until GPU Clear/Draw initializes it.
struct RenderTargetTextureInfo
{
	std::uint32_t width = 0;
	std::uint32_t height = 0;
	TextureFormat format = TextureFormat::RGBA8_UNorm;
	std::uint64_t revision = 0;
	bool contentsValid = false;
};

}
